// Builds the OpenAPI 3.1 document from the Zod contract. Component schemas
// are generated by z.toJSONSchema (JSON Schema 2020-12, which OpenAPI 3.1
// uses); only paths and descriptions are written here.
import { z } from 'zod';

import {
  CURRENCIES,
  COUNTRY_CODES,
  DEPARTMENTS,
  EMPLOYMENT_STATUSES,
  LEVELS,
} from '../source-workbook/constants.js';
import {
  COMPARISON_CURRENCIES,
  DEFAULT_PAGE_SIZE,
  MAX_PAGE_SIZE,
  MAX_SEARCH_LENGTH,
  DASHBOARD_BREAKDOWNS,
  DASHBOARD_LIST_MAX_PAGE_SIZE,
  DASHBOARD_NO_ADJUSTMENT_MONTHS,
  DASHBOARD_PERIOD_DAYS,
  PATHS,
  REQUEST_STATUSES,
  SORT_DIRECTIONS,
  SORT_FIELDS,
  contractRegistry,
} from './contract.js';

const ref = (id: string) => ({ $ref: `#/components/schemas/${id}` });
const json = (id: string, description: string) => ({ description, content: { 'application/json': { schema: ref(id) } } });
const error = (description: string) => json('ErrorResponse', description);

/** OpenAPI path template from an Express path ("/:id" -> "/{id}"). */
const openApiPath = (expressPath: string): string => expressPath.replace(/:([A-Za-z]+)/g, '{$1}');

const queryParam = (name: string, schema: Record<string, unknown>, description?: string) => ({
  name, in: 'query', required: false, ...(description ? { description } : {}), schema,
});

/**
 * GET /employees query parameters. Values come from the same constants as
 * DirectoryQueryParams; http-openapi.test.ts checks the two agree.
 */
const DIRECTORY_PARAMETERS = [
  queryParam('q', { type: 'string', maxLength: MAX_SEARCH_LENGTH },
    'Employee ID (exact or prefix), first, last, or full name (partial, case-insensitive), or exact email (case-insensitive). "%", "_", and "\\" are literal.'),
  queryParam('department', { type: 'string', enum: [...DEPARTMENTS] }),
  queryParam('country', { type: 'string', enum: [...COUNTRY_CODES] }),
  queryParam('currency', { type: 'string', enum: [...CURRENCIES] }, 'Currency of the selected compensation record.'),
  queryParam('level', { type: 'string', enum: [...LEVELS] }),
  queryParam('status', { type: 'string', enum: [...EMPLOYMENT_STATUSES] }),
  queryParam('sort', { type: 'string', enum: [...SORT_FIELDS], default: 'name' },
    'Salary sorts compare unrounded USD values computed in MySQL from the saved rate, and require comparisonCurrency=USD. Ties break on employee ID.'),
  queryParam('direction', { type: 'string', enum: [...SORT_DIRECTIONS], default: 'asc' }),
  queryParam('page', { type: 'integer', minimum: 1, maximum: 1_000_000, default: 1 }),
  queryParam('pageSize', { type: 'integer', minimum: 1, maximum: MAX_PAGE_SIZE, default: DEFAULT_PAGE_SIZE }),
  queryParam('comparisonCurrency', { type: 'string', enum: [...COMPARISON_CURRENCIES] }, 'Required when sort is a salary field.'),
];

const EMPLOYEE_CODE_PARAMETER = { name: 'employeeCode', in: 'path', required: true, schema: { type: 'string', pattern: '^ACME[0-9]{5}$' } };
const REQUEST_ID_PARAMETER = { name: 'requestId', in: 'path', required: true, schema: { type: 'string', format: 'uuid' } };
const IDEMPOTENCY_KEY_PARAMETER = {
  name: 'Idempotency-Key',
  in: 'header',
  required: true,
  description: 'Unique per operation attempt; reuse it only to retry the same command. The same key with the same command returns the original result (with an Idempotency-Replayed: true header); with different data it returns DUPLICATE_OPERATION.',
  schema: { type: 'string', pattern: '^[A-Za-z0-9_-]{16,128}$' },
};
const SALARY_REQUEST_LIST_PARAMETERS = [
  queryParam('q', { type: 'string', maxLength: MAX_SEARCH_LENGTH }, 'Employee ID (exact or prefix), name (partial), or exact email.'),
  queryParam('department', { type: 'string', enum: [...DEPARTMENTS] }, 'Admin HR only; Scoped HR receives VALIDATION_ERROR.'),
  queryParam('status', { type: 'string', enum: [...REQUEST_STATUSES] }),
  queryParam('sort', { type: 'string', enum: ['createdAt'], default: 'createdAt' }),
  queryParam('direction', { type: 'string', enum: [...SORT_DIRECTIONS], default: 'desc' }),
  queryParam('page', { type: 'integer', minimum: 1, maximum: 1_000_000, default: 1 }),
  queryParam('pageSize', { type: 'integer', minimum: 1, maximum: MAX_PAGE_SIZE, default: DEFAULT_PAGE_SIZE }),
];
const DASHBOARD_FILTER_PARAMETERS = [
  queryParam('department', { type: 'string', enum: [...DEPARTMENTS] }),
  queryParam('country', { type: 'string', enum: [...COUNTRY_CODES] }),
  queryParam('currency', { type: 'string', enum: [...CURRENCIES] }, 'Currency of the selected compensation record, change, or request.'),
  queryParam('level', { type: 'string', enum: [...LEVELS] }),
  queryParam('employmentStatus', { type: 'string', enum: [...EMPLOYMENT_STATUSES] },
    'Sections that cover currently working employees only report a non-working value in notApplied instead of ignoring it.'),
];
const PERIOD_DAYS_PARAMETER = queryParam('periodDays', { type: 'string', enum: [...DASHBOARD_PERIOD_DAYS], default: '30' },
  'Recent changes: compensation records created in the last N days (measured back from now). Effective date is not used.');
const NO_ADJUSTMENT_MONTHS_PARAMETER = queryParam('noAdjustmentMonths', { type: 'string', enum: [...DASHBOARD_NO_ADJUSTMENT_MONTHS], default: '12' },
  'Without recent adjustment: no non-import record created in the last N months.');
const DASHBOARD_PAGE_PARAMETERS = [
  queryParam('page', { type: 'integer', minimum: 1, maximum: 1_000_000, default: 1 }),
  queryParam('pageSize', { type: 'integer', minimum: 1, maximum: DASHBOARD_LIST_MAX_PAGE_SIZE, default: DEFAULT_PAGE_SIZE }),
];
const DASHBOARD_ERRORS = {
  400: error('VALIDATION_ERROR: unknown, repeated, or unsupported query value.'),
  401: error('UNAUTHENTICATED'),
  500: error('INTERNAL_ERROR'),
  503: error('SERVICE_UNAVAILABLE'),
};
const dashboardOperation = (operationId: string, summary: string, schema: string, parameters: unknown[], description: string) => ({
  get: {
    operationId,
    summary,
    description: `${description} Every figure uses the caller's current scope; an empty scope returns access.hasEmployeeAccess = false and no figures.`,
    security: [{ bearerAuth: [] }],
    parameters,
    responses: { 200: json(schema, 'Permission-filtered analytics. Native currencies are never combined.'), ...DASHBOARD_ERRORS },
  },
});

const SALARY_COMMON_ERRORS = {
  400: error('VALIDATION_ERROR, with a reason such as PREVIEW_EXPIRED, PREVIEW_MISMATCH, SALARY_BAND, PERCENTAGE_RANGE, PAST_EFFECTIVE_DATE, FUTURE_CHANGE_EXISTS, NOTE_REQUIRED, or IDEMPOTENCY_KEY_REQUIRED.'),
  401: error('UNAUTHENTICATED'),
  500: error('INTERNAL_ERROR'),
  503: error('SERVICE_UNAVAILABLE: database unavailable or a lock wait timed out. Safe to retry with the same Idempotency-Key.'),
};

function componentSchemas(): Record<string, unknown> {
  const { schemas } = z.toJSONSchema(contractRegistry, {
    target: 'draft-2020-12',
    uri: (id) => `#/components/schemas/${id}`,
  });
  // $schema and $id are per-document keywords; OpenAPI components omit them.
  return Object.fromEntries(
    Object.entries(schemas).map(([id, schema]) => {
      const { $schema: _schema, $id: _id, ...rest } = schema;
      return [id, rest];
    }),
  );
}

export function buildOpenApiDocument(): Record<string, unknown> {
  return {
    openapi: '3.1.0',
    info: {
      title: 'ACME Compensation API',
      version: '1.0.0',
      description: 'Backend API for the Next.js server. Browsers do not call it directly; no CORS is enabled.',
    },
    paths: {
      [PATHS.health]: {
        get: {
          operationId: 'getHealth',
          summary: 'Liveness check',
          responses: { 200: json('HealthResponse', 'The process is running.') },
        },
      },
      [PATHS.login]: {
        post: {
          operationId: 'login',
          summary: 'Sign in and receive a two-hour session token',
          description: 'Five failed attempts per caller and email address per 15 minutes; successful logins do not count.',
          requestBody: { required: true, content: { 'application/json': { schema: ref('LoginRequest') } } },
          responses: {
            200: json('LoginResponse', 'Signed in.'),
            400: error('VALIDATION_ERROR'),
            401: error('INVALID_CREDENTIALS: unknown email, wrong password, or inactive user (one response).'),
            413: error('VALIDATION_ERROR: body too large.'),
            429: error('RATE_LIMITED'),
            500: error('INTERNAL_ERROR'),
          },
        },
      },
      [PATHS.me]: {
        get: {
          operationId: 'getCurrentUser',
          summary: 'Current HR user, scopes, and session expiry',
          security: [{ bearerAuth: [] }],
          responses: {
            200: json('CurrentUserResponse', 'Current state from the database.'),
            401: error('UNAUTHENTICATED'),
            500: error('INTERNAL_ERROR'),
          },
        },
      },
      [PATHS.logout]: {
        post: {
          operationId: 'logout',
          summary: 'Revoke the session (safe to repeat)',
          security: [{ bearerAuth: [] }],
          responses: {
            204: { description: 'Session revoked, or already revoked.' },
            401: error('UNAUTHENTICATED: missing or invalid token.'),
            500: error('INTERNAL_ERROR'),
          },
        },
      },
      [PATHS.openapi]: {
        get: {
          operationId: 'getOpenApiDocument',
          summary: 'This document',
          responses: { 200: { description: 'OpenAPI 3.1 document.', content: { 'application/json': {} } } },
        },
      },
      [PATHS.employees]: {
        get: {
          operationId: 'listEmployees',
          summary: 'Search, filter, sort, and page the employees in the caller\'s scope',
          description: 'Scope, filters, sorting, LIMIT, and OFFSET all run in MySQL. Totals count only employees in scope.',
          security: [{ bearerAuth: [] }],
          parameters: DIRECTORY_PARAMETERS,
          responses: {
            200: json('DirectoryResponse', 'One page. A page after the last page has no rows and correct totals.'),
            400: error('VALIDATION_ERROR: invalid, unknown, or repeated parameter; salary sort without comparisonCurrency=USD; or salary sort with no saved INR rate.'),
            401: error('UNAUTHENTICATED'),
            500: error('INTERNAL_ERROR'),
          },
        },
      },
      [openApiPath(PATHS.employee)]: {
        get: {
          operationId: 'getEmployee',
          summary: 'One employee with selected compensation and full compensation history',
          security: [{ bearerAuth: [] }],
          parameters: [{ name: 'employeeCode', in: 'path', required: true, schema: { type: 'string', pattern: '^ACME[0-9]{5}$' } }],
          responses: {
            200: json('EmployeeDetailResponse', 'The employee.'),
            401: error('UNAUTHENTICATED'),
            404: error('NOT_FOUND: unknown and out-of-scope employees return the same body.'),
            500: error('INTERNAL_ERROR'),
          },
        },
      },
      [PATHS.directoryOptions]: {
        get: {
          operationId: 'getDirectoryOptions',
          summary: 'Filter and sort values available inside the caller\'s scope',
          security: [{ bearerAuth: [] }],
          responses: {
            200: json('DirectoryOptionsResponse', 'Values present in scope. Salary sorts are omitted when no rate is loaded.'),
            401: error('UNAUTHENTICATED'),
            500: error('INTERNAL_ERROR'),
          },
        },
      },
      [PATHS.assistantMessages]: {
        post: {
          operationId: 'sendAssistantMessages',
          summary: 'Ask the read-only compensation assistant',
          description: 'Read-only. The server derives identity and scope from the Bearer token. Tools return permission-filtered cards; '
            + 'the answer text is model-written. At most 4 tool rounds and 45 seconds per request.',
          security: [{ bearerAuth: [] }],
          requestBody: { required: true, content: { 'application/json': { schema: ref('AssistantMessagesRequest') } } },
          responses: {
            200: json('AssistantMessagesResponse', 'The answer, tool calls, cards, and limitations.'),
            400: error('VALIDATION_ERROR: invalid conversation.'),
            401: error('UNAUTHENTICATED'),
            500: error('INTERNAL_ERROR'),
            503: error('ASSISTANT_UNAVAILABLE: no model configured, model timeout, or provider error. Other routes are unaffected.'),
          },
        },
      },
      [openApiPath(PATHS.salaryAdjustmentPreview)]: {
        post: {
          operationId: 'previewSalaryAdjustment',
          summary: 'Preview one salary adjustment (writes nothing)',
          description: 'Returns exact old and new values, the salary band, warnings, and a five-minute preview token. '
            + 'confirmationMode is DIRECT_APPLY for Admin HR and SUBMIT_REQUEST for Scoped HR.',
          security: [{ bearerAuth: [] }],
          parameters: [EMPLOYEE_CODE_PARAMETER],
          requestBody: { required: true, content: { 'application/json': { schema: ref('SalaryAdjustmentCommand') } } },
          responses: {
            200: json('SalaryAdjustmentPreview', 'A valid adjustment.'),
            ...SALARY_COMMON_ERRORS,
            404: error('NOT_FOUND: unknown and out-of-scope employees return the same body.'),
            409: error('PENDING_REQUEST_EXISTS (Scoped HR).'),
            422: error('EMPLOYEE_INELIGIBLE'),
          },
        },
      },
      [openApiPath(PATHS.salaryAdjustments)]: {
        post: {
          operationId: 'applySalaryAdjustment',
          summary: 'Admin HR: apply the exact previewed adjustment',
          description: 'Creates one immutable compensation version and marks any pending request STALE, in one transaction.',
          security: [{ bearerAuth: [] }],
          parameters: [EMPLOYEE_CODE_PARAMETER, IDEMPOTENCY_KEY_PARAMETER],
          requestBody: { required: true, content: { 'application/json': { schema: ref('SalaryAdjustmentConfirmation') } } },
          responses: {
            201: json('SalaryAdjustmentResult', 'The new compensation version (or the original result for a replay).'),
            ...SALARY_COMMON_ERRORS,
            403: error('FORBIDDEN: Scoped HR.'),
            404: error('NOT_FOUND'),
            409: error('STALE_VERSION (fetch and confirm a fresh preview) or DUPLICATE_OPERATION.'),
            422: error('EMPLOYEE_INELIGIBLE'),
          },
        },
      },
      [openApiPath(PATHS.employeeSalaryAdjustmentRequests)]: {
        post: {
          operationId: 'submitSalaryAdjustmentRequest',
          summary: 'Scoped HR: submit the exact previewed adjustment for approval',
          description: 'Creates one PENDING request and no compensation record.',
          security: [{ bearerAuth: [] }],
          parameters: [EMPLOYEE_CODE_PARAMETER, IDEMPOTENCY_KEY_PARAMETER],
          requestBody: { required: true, content: { 'application/json': { schema: ref('SalaryAdjustmentConfirmation') } } },
          responses: {
            201: json('SalaryRequestResponse', 'The pending request (or the original request for a replay).'),
            ...SALARY_COMMON_ERRORS,
            403: error('FORBIDDEN: Admin HR applies directly.'),
            404: error('NOT_FOUND'),
            409: error('STALE_VERSION, PENDING_REQUEST_EXISTS, or DUPLICATE_OPERATION.'),
            422: error('EMPLOYEE_INELIGIBLE'),
          },
        },
      },
      [PATHS.salaryAdjustmentRequests]: {
        get: {
          operationId: 'listSalaryAdjustmentRequests',
          summary: 'Requests for employees in the caller\'s current scope (all for Admin HR)',
          security: [{ bearerAuth: [] }],
          parameters: SALARY_REQUEST_LIST_PARAMETERS,
          responses: {
            200: json('SalaryRequestList', 'One page, sorted by creation time.'),
            ...SALARY_COMMON_ERRORS,
          },
        },
      },
      [openApiPath(PATHS.salaryAdjustmentRequest)]: {
        get: {
          operationId: 'getSalaryAdjustmentRequest',
          summary: 'One request',
          security: [{ bearerAuth: [] }],
          parameters: [REQUEST_ID_PARAMETER],
          responses: {
            200: json('SalaryRequestResponse', 'The request.'),
            401: error('UNAUTHENTICATED'),
            404: error('NOT_FOUND: unknown and out-of-scope requests return the same body.'),
            500: error('INTERNAL_ERROR'),
            503: error('SERVICE_UNAVAILABLE'),
          },
        },
      },
      [openApiPath(PATHS.salaryAdjustmentRequestApprove)]: {
        post: {
          operationId: 'approveSalaryAdjustmentRequest',
          summary: 'Admin HR: approve the exact request',
          description: 'Rechecks requester status and scope, eligibility, salary band, effective date, future changes, and compensation version. '
            + 'A failed recheck caused by changed state marks the request STALE.',
          security: [{ bearerAuth: [] }],
          parameters: [REQUEST_ID_PARAMETER, IDEMPOTENCY_KEY_PARAMETER],
          responses: {
            200: json('SalaryRequestApproval', 'The approved request and the new compensation version.'),
            ...SALARY_COMMON_ERRORS,
            403: error('FORBIDDEN: Scoped HR.'),
            404: error('NOT_FOUND'),
            409: error('STALE_VERSION (request marked stale), REQUEST_NOT_PENDING, or DUPLICATE_OPERATION.'),
            422: error('EMPLOYEE_INELIGIBLE (request marked stale).'),
          },
        },
      },
      [openApiPath(PATHS.salaryAdjustmentRequestCancel)]: {
        post: {
          operationId: 'cancelSalaryAdjustmentRequest',
          summary: 'Admin HR: cancel a pending request with a note',
          description: 'Changes no compensation.',
          security: [{ bearerAuth: [] }],
          parameters: [REQUEST_ID_PARAMETER, IDEMPOTENCY_KEY_PARAMETER],
          requestBody: { required: true, content: { 'application/json': { schema: ref('SalaryRequestCancellation') } } },
          responses: {
            200: json('SalaryRequestResponse', 'The cancelled request.'),
            ...SALARY_COMMON_ERRORS,
            403: error('FORBIDDEN: Scoped HR.'),
            404: error('NOT_FOUND'),
            409: error('REQUEST_NOT_PENDING or DUPLICATE_OPERATION.'),
          },
        },
      },
      [PATHS.dashboardSummary]: dashboardOperation('getDashboardSummary', 'Top dashboard figures', 'DashboardSummaryResponse',
        [...DASHBOARD_FILTER_PARAMETERS, PERIOD_DAYS_PARAMETER, NO_ADJUSTMENT_MONTHS_PARAMETER],
        'Headcount by status, current spending and upcoming commitment by native currency, request counts, recent-change and without-adjustment counts, and an optional USD comparison.'),
      [PATHS.dashboardBreakdowns]: dashboardOperation('getDashboardBreakdown', 'One compensation breakdown', 'DashboardBreakdownResponse',
        [...DASHBOARD_FILTER_PARAMETERS, queryParam('breakdown', { type: 'string', enum: [...DASHBOARD_BREAKDOWNS], default: 'DEPARTMENT' })],
        'Count, totals, average, median, minimum, and maximum annual cash per group and native currency. Average and median round half-up to cents.'),
      [PATHS.dashboardRecentChanges]: dashboardOperation('getDashboardRecentChanges', 'Recently recorded compensation changes', 'DashboardRecentChangesResponse',
        [...DASHBOARD_FILTER_PARAMETERS, PERIOD_DAYS_PARAMETER, ...DASHBOARD_PAGE_PARAMETERS],
        'Newest record first. INITIAL_IMPORT is excluded; a future-effective change recorded in the period is included.'),
      [PATHS.dashboardWithoutRecentAdjustment]: dashboardOperation('getDashboardWithoutRecentAdjustment', 'Working employees without a recorded adjustment', 'DashboardWithoutAdjustmentResponse',
        [...DASHBOARD_FILTER_PARAMETERS, NO_ADJUSTMENT_MONTHS_PARAMETER, ...DASHBOARD_PAGE_PARAMETERS],
        'No recorded salary adjustment since import or during the selected period. The initial import is not an adjustment.'),
      [PATHS.mcp]: {
        post: {
          operationId: 'mcp',
          summary: 'Read-only MCP endpoint (Streamable HTTP, stateless JSON-RPC)',
          description: 'Model Context Protocol endpoint exposing the same five read-only tools as the assistant. '
            + 'Use an MCP client. Requests with an Origin header are rejected with 403; GET and DELETE return 405.',
          security: [{ bearerAuth: [] }],
          requestBody: { required: true, content: { 'application/json': { schema: { type: 'object', description: 'JSON-RPC 2.0 message.' } } } },
          responses: {
            200: { description: 'JSON-RPC response (application/json or text/event-stream).' },
            401: error('UNAUTHENTICATED'),
            403: { description: 'Request carried an Origin header.' },
          },
        },
      },
    },
    components: {
      schemas: componentSchemas(),
      securitySchemes: { bearerAuth: { type: 'http', scheme: 'bearer', bearerFormat: 'JWT' } },
    },
  };
}
